// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface ILendingPool {
    function getCollateralValue(address user) external view returns (uint256);
}

/// @title LiquidityPool - AMM pool with lending integration
contract LiquidityPool is ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable tokenA;
    IERC20 public immutable tokenB;

    uint256 public reserveA;
    uint256 public reserveB;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    // LP token price = total pool value / total supply
    // Used by lending protocols as price oracle for LP token collateral

    event Mint(address indexed to, uint256 amount);
    event Burn(address indexed from, uint256 amount);
    event Swap(address indexed user, address tokenIn, uint256 amountIn, uint256 amountOut);

    constructor(address _tokenA, address _tokenB) {
        tokenA = IERC20(_tokenA);
        tokenB = IERC20(_tokenB);
    }

    /// @notice Returns the current price of 1 LP token in terms of tokenA
    /// @dev Used by lending protocols to value LP token collateral
    function getLPTokenPrice() public view returns (uint256) {
        if (totalSupply == 0) return 1e18;
        // Price = (reserveA + reserveB * priceB/priceA) / totalSupply
        // Simplified: assuming 1:1 price ratio for tokenA:tokenB
        return (reserveA + reserveB) * 1e18 / totalSupply;
    }

    /// @notice Add liquidity to the pool
    function addLiquidity(uint256 amountA, uint256 amountB) external nonReentrant returns (uint256 liquidity) {
        tokenA.safeTransferFrom(msg.sender, address(this), amountA);
        tokenB.safeTransferFrom(msg.sender, address(this), amountB);

        if (totalSupply == 0) {
            liquidity = sqrt(amountA * amountB);
        } else {
            liquidity = min(
                (amountA * totalSupply) / reserveA,
                (amountB * totalSupply) / reserveB
            );
        }

        require(liquidity > 0, "Insufficient liquidity minted");

        reserveA += amountA;
        reserveB += amountB;
        totalSupply += liquidity;
        balanceOf[msg.sender] += liquidity;

        emit Mint(msg.sender, liquidity);
    }

    /// @notice Remove liquidity from the pool
    function removeLiquidity(uint256 liquidity) external nonReentrant returns (uint256 amountA, uint256 amountB) {
        require(balanceOf[msg.sender] >= liquidity, "Insufficient balance");
        require(liquidity > 0, "Zero liquidity");

        amountA = (liquidity * reserveA) / totalSupply;
        amountB = (liquidity * reserveB) / totalSupply;

        require(amountA > 0 && amountB > 0, "Insufficient amounts");

        // Update state
        balanceOf[msg.sender] -= liquidity;
        totalSupply -= liquidity;
        reserveA -= amountA;
        reserveB -= amountB;

        // Transfer tokens out
        tokenA.safeTransfer(msg.sender, amountA);
        tokenB.safeTransfer(msg.sender, amountB);

        emit Burn(msg.sender, liquidity);
    }

    /// @notice Swap tokenA for tokenB or vice versa
    function swap(address tokenIn, uint256 amountIn, uint256 minAmountOut) external nonReentrant returns (uint256 amountOut) {
        require(tokenIn == address(tokenA) || tokenIn == address(tokenB), "Invalid token");
        require(amountIn > 0, "Zero amount");

        bool isTokenA = tokenIn == address(tokenA);

        (uint256 reserveIn, uint256 reserveOut) = isTokenA 
            ? (reserveA, reserveB) 
            : (reserveB, reserveA);

        // 0.3% fee
        uint256 amountInWithFee = amountIn * 997;
        amountOut = (amountInWithFee * reserveOut) / (reserveIn * 1000 + amountInWithFee);

        require(amountOut >= minAmountOut, "Slippage exceeded");
        require(amountOut < reserveOut, "Insufficient reserve");

        // Transfer in
        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);

        // Update reserves
        if (isTokenA) {
            reserveA += amountIn;
            reserveB -= amountOut;
        } else {
            reserveB += amountIn;
            reserveA -= amountOut;
        }

        // Transfer out
        IERC20(isTokenA ? address(tokenB) : address(tokenA)).safeTransfer(msg.sender, amountOut);

        emit Swap(msg.sender, tokenIn, amountIn, amountOut);
    }

    function sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }

    function min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}

/// @title LendingVault - Accepts LP tokens as collateral
/// @dev Uses LiquidityPool.getLPTokenPrice() to value collateral
contract LendingVault is ReentrancyGuard {
    using SafeERC20 for IERC20;

    LiquidityPool public immutable pool;
    IERC20 public immutable borrowToken;

    mapping(address => uint256) public collateralDeposited; // LP tokens
    mapping(address => uint256) public borrowedAmount;

    uint256 public constant COLLATERAL_FACTOR = 80; // 80% LTV
    uint256 public constant LIQUIDATION_THRESHOLD = 90; // 90%
    uint256 public constant PRECISION = 100;

    event Deposit(address indexed user, uint256 amount);
    event Borrow(address indexed user, uint256 amount);
    event Repay(address indexed user, uint256 amount);
    event Liquidate(address indexed user, address indexed liquidator, uint256 amount);

    constructor(address _pool, address _borrowToken) {
        pool = LiquidityPool(_pool);
        borrowToken = IERC20(_borrowToken);
    }

    /// @notice Deposit LP tokens as collateral
    function deposit(uint256 amount) external nonReentrant {
        require(amount > 0, "Zero amount");
        IERC20(address(pool)).safeTransferFrom(msg.sender, address(this), amount);
        collateralDeposited[msg.sender] += amount;
        emit Deposit(msg.sender, amount);
    }

    /// @notice Get collateral value for a user
    function getCollateralValue(address user) public view returns (uint256) {
        uint256 lpPrice = pool.getLPTokenPrice();
        return (collateralDeposited[user] * lpPrice) / 1e18;
    }

    /// @notice Borrow against LP token collateral
    function borrow(uint256 amount) external nonReentrant {
        require(amount > 0, "Zero amount");

        uint256 collateralValue = getCollateralValue(msg.sender);
        uint256 maxBorrow = (collateralValue * COLLATERAL_FACTOR) / PRECISION;

        require(borrowedAmount[msg.sender] + amount <= maxBorrow, "Exceeds borrow limit");

        borrowedAmount[msg.sender] += amount;
        borrowToken.safeTransfer(msg.sender, amount);

        emit Borrow(msg.sender, amount);
    }

    /// @notice Repay borrowed amount
    function repay(uint256 amount) external nonReentrant {
        require(amount > 0, "Zero amount");
        require(borrowedAmount[msg.sender] >= amount, "Exceeds debt");

        borrowToken.safeTransferFrom(msg.sender, address(this), amount);
        borrowedAmount[msg.sender] -= amount;

        emit Repay(msg.sender, amount);
    }

    /// @notice Liquidate undercollateralized position
    function liquidate(address user) external nonReentrant {
        uint256 collateralValue = getCollateralValue(user);
        uint256 debt = borrowedAmount[user];

        require(debt > 0, "No debt");
        require((debt * PRECISION) > (collateralValue * LIQUIDATION_THRESHOLD), "Position healthy");

        // Liquidator repays debt and receives collateral
        borrowToken.safeTransferFrom(msg.sender, address(this), debt);

        uint256 collateral = collateralDeposited[user];
        collateralDeposited[user] = 0;
        borrowedAmount[user] = 0;

        IERC20(address(pool)).safeTransfer(msg.sender, collateral);

        emit Liquidate(user, msg.sender, collateral);
    }
}
